graphql:
# What each customer's orders came to, the largest first: the BI analyst's view, which a support
# agent's role cannot read.
query RevenueByCustomer {
  s__viewRevenueByCustomer(order_by: [{ revenue: desc }], limit: 20) {
    name
    region
    orders
    revenue
  }
}

# The portfolio's premium and indemnity by crop year, summed on the server, the costliest year
# first: the years it lost money on, to set beside each year's rain and heat.
query LossesByYear {
  a__viewLossesAndWeatherGroupBy(by: [year], order_by: [{ aggregate: { sum: { indemnity: desc } } }]) {
    groupKey
    aggregate {
      count
      sum {
        premium
        indemnity
        hotDays
      }
    }
  }
}

# The readiness memo's items: every award on a client's schedule that its federal award records do
# not bear out in 2023 -- a timing difference, a missing award, or an award the schedule leaves out.
query OpenItems {
  a__viewReadiness(
    where: { finding: { in: ["timing", "missing", "unrecorded"] } }
    order_by: [{ clientName: asc }, { aln: asc }]
    limit: 50
  ) {
    clientName
    state
    aln
    programName
    awardNumber
    amountExpended
    obligatedFy2023
    obligatedEarlier
    finding
  }
}

# Each client's schedule by what the auditor finds: how many awards and how many dollars matched,
# were obligated earlier, are missing, were passed through or were left out.
query FindingsByClient {
  a__viewReadinessGroupBy(by: [clientName, finding], order_by: [{ groupKey: { clientName: asc } }]) {
    groupKey
    aggregate {
      count
      sum {
        amountExpended
      }
    }
  }
}

# The same match on the public record: the Assistance Listings whose direct award lines in the
# three states' 2023 Single Audits USAspending most often has no obligation for.
query PublicUnmatched {
  a__viewPublicMatch(
    where: { isDirect: { eq: "Y" } }
    order_by: [{ unmatchedLines: desc }]
    limit: 20
  ) {
    state
    aln
    programName
    lines
    matchedLines
    unmatchedLines
    expended
    obligated
  }
}

# The end-of-day dashboard for 1 October: each of London's totals that day, with the postings
# behind it, the drill-down read live from the ledger. Run as ops_analyst: the postings are those
# the ledger's rules let operations see, counterparties withheld.
query EodDashboard {
  b__viewEodTotals(
    where: { businessDate: { eq: "2026-10-01" }, branch: { eq: "London" } }
    order_by: [{ netMovement: asc }]
    limit: 10
  ) {
    businessDate
    branch
    product
    currency
    postingCount
    netMovement
    postings(order_by: [{ amount: asc }], limit: 5) {
      transactionId
      kind
      amount
      counterparty
      status
      updatedAt
    }
  }
}

# Which cash needs a currency transaction report: each person and business day whose cash in, or
# cash out, comes to more than $10,000 across their accounts and branches.
query CtrRequired {
  b__viewCtrRequired(
    order_by: [{ businessDay: asc }, { person: asc }, { direction: asc }]
    limit: 20
  ) {
    person
    businessDay
    direction
    multipleTransactions
    branches
    accountNumbers
    cashTotal
  }
}

# The at-risk list over GraphQL: every current customer with the churn model's score and what raises
# it, riskiest first.
query AtRisk {
  c__viewAtRisk(order_by: [{ score: desc }], limit: 20) {
    customerId
    email
    region
    plan
    score
    reasons
  }
}

# Every attached disk the daily review flags, by team: its status and the incident that decides it.
query OpenReview {
  c__viewDailyReview(where: { status: { neq: "compliant" } }, order_by: [{ application: asc }, { status: asc }], limit: 50) {
    application
    resourceName
    status
    incidentNumber
  }
}

# Revenue, orders and the average order of each segment, by year: what a bidder is shown of sales.
query RevenueBySegment {
  d__viewRevenueBySegment(order_by: [{ year: asc }, { segment: asc }]) {
    year
    segment
    orders
    revenue
    averageOrder
  }
}

# Each check of the seller's records, and how many rows fail it.
query DataQuality {
  d__viewDataQuality {
    tableName
    dataCheck
    totalRows
    failingRows
  }
}

# What was known about Alfreds Futterkiste, from which source, and since when: the customer's hub,
# and along KNOWN_AS, at every date anything about it was loaded, each system's version then.
query WhatWasKnown {
  v__viewHubCustomer(where: { customerId: { eq: "ALFKI" } }) {
    customerId
    viewCustomerAsKnowns(order_by: [{ asOf: asc }]) {
      asOf
      ordersSource
      ordersLoadDate
      ordersAddress
      crmSource
      crmLoadDate
      crmAddress
    }
  }
}

# The vault walked hub to link to hub: a customer, the orders it placed, and the products in them
# with every version of each product's name and price.
query CustomerOrdersProducts {
  v__viewHubCustomer(where: { customerId: { eq: "ALFKI" } }) {
    customerId
    viewLinkCustomerOrders {
      viewHubOrder {
        orderId
        viewLinkOrderProducts {
          viewHubProduct {
            productId
            viewSatProducts {
              loadDate
              productName
              unitPrice
            }
          }
        }
      }
    }
  }
}

# Which neighborhoods have the most complaints near active construction: the stored view, most
# complaints first, with the active permits they are about.
query ComplaintsNearConstruction {
  c__viewComplaintsNearConstruction(order_by: [{ complaints: desc }]) {
    neighborhood
    complaints
    activePermits
  }
}

# The complaints table is one table over a CSV file a month: its complaints by neighborhood and
# status, across every monthly file the folder holds.
query ComplaintsByNeighborhoodAndStatus {
  c__complaintsGroupBy(
    by: [neighborhood, status]
    order_by: [{ aggregate: { count: desc } }]
  ) {
    groupKey
    aggregate {
      count
    }
  }
}

# Building permits, read from a Parquet file: how many are active in each neighborhood and what
# the work is worth.
query ActivePermitsByNeighborhood {
  c__permitsGroupBy(by: [neighborhood, status], order_by: [{ groupKey: { neighborhood: asc } }]) {
    groupKey
    aggregate {
      count
      sum {
        valuation
      }
    }
  }
}

# The city budget, read from an Excel workbook: what each neighborhood is budgeted.
query BudgetByNeighborhood {
  c__budgetGroupBy(by: [neighborhood], order_by: [{ aggregate: { sum: { amount: desc } } }]) {
    groupKey
    aggregate {
      sum {
        amount
      }
    }
  }
}

# Inspections of permitted work, read from a JSON file: how they turned out.
query InspectionResults {
  c__inspectionsGroupBy(by: [result], order_by: [{ aggregate: { count: desc } }]) {
    groupKey
    aggregate {
      count
    }
  }
}

# The corporate groups the bank lends most to, each borrower counted with the group Wikidata says
# owns it: their committed exposure against the 25% large-exposure limit.
query GroupsOverLimit {
  g__viewGroupExposure(order_by: [{ committedEur: desc }], limit: 10) {
    groupName
    borrowers
    committedEur
    pctOfTier1
    overLimit
  }
}

# What each borrower owes the bank, alone, summed by the bank's own sectors: the view its books give
# without knowing who owns whom.
query BySector {
  g__viewBorrowerExposureGroupBy(by: [sector], order_by: [{ aggregate: { sum: { committedEur: desc } } }]) {
    groupKey
    aggregate {
      count
      sum {
        committedEur
      }
      max {
        pctOfTier1
      }
    }
  }
}

# The storefront's order-history screen, reshaped for Provisa: the same orders, lines and products
# the app read from Hasura. Run as ana, a customer: her own orders and nobody else's, by the row
# rules the import carried. (Hasura's shape: hasura/app-queries/my-orders.graphql.)
query MyOrders {
  s__orders(order_by: [{ placedAt: desc }]) {
    id
    status
    totalCents
    placedAt
    items {
      quantity
      unitPriceCents
      product {
        name
        sku
      }
    }
  }
}

# The storefront's profile screen, reshaped for Provisa: a read by key is a filter on the table,
# and the full name the Hasura computed field returned is put together from the two names. Run as
# ana, it returns her own row alone. (Hasura's shape: hasura/app-queries/my-profile.graphql.)
query MyProfile {
  s__customers(where: { id: { eq: 1 } }) {
    id
    givenName
    familyName
    email
  }
}

# The support desk's order screen, reshaped for Provisa -- and what Hasura could not do: beside
# each order's customer, the Salesforce account the customer buys for, from the sales team's org.
# Run as support. (Hasura's shape: hasura/app-queries/support-order.graphql.)
query OrdersWithAccounts {
  s__orders(order_by: [{ totalCents: desc }], limit: 20) {
    id
    status
    totalCents
    customer {
      givenName
      familyName
      email
      account {
        name
        industry
        billingCity
      }
    }
  }
}

# How many cases each first-level reviewer has, and the highest score among them.
query CasesByReviewer {
  b__viewReviewQueueGroupBy(by: [reviewer], order_by: [{ groupKey: { reviewer: asc } }]) {
    groupKey
    aggregate {
      count
      max {
        score
      }
    }
  }
}

# How many messages speak of each watch-list deal, and how close the closest one reads to it.
query MatchesByDeal {
  b__dealMatchGroupBy(by: [dealId], order_by: [{ groupKey: { dealId: asc } }]) {
    groupKey
    aggregate {
      count
      max {
        meaningMatch
      }
    }
  }
}

# The bank's own log of who read customer records: how many each employee read.
query CustomerReadsByEmployee {
  b__customerAccessGroupBy(by: [employeeId], order_by: [{ aggregate: { sum: { recordsRead: desc } } }]) {
    groupKey
    aggregate {
      count
      sum {
        recordsRead
      }
    }
  }
}

# The book's total insured value by FEMA's all-hazard risk rating of the counties it is written in:
# how much of the exposure sits where the risk is Relatively High or Very High.
query TivByRiskRating {
  i__viewExposureByCountyGroupBy(by: [riskRating], order_by: [{ aggregate: { sum: { tiv: desc } } }]) {
    groupKey
    aggregate {
      count
      sum {
        tiv
        policies
      }
    }
  }
}

# The counties holding the most insured value at a national all-hazard risk percentile of 90 or
# more: where the insurer's accumulation meets the highest hazard risk.
query MostExposedHighRiskCounties {
  i__viewExposureByCounty(
    where: { riskNationalPctl: { gte: 90 } }
    order_by: [{ tiv: desc }]
    limit: 10
  ) {
    countyName
    stateAbbr
    policies
    tiv
    riskRating
    wildfireDirectExposure
    stormDamage_5y
  }
}

# The fund's spending by its region, for its staff: each region's counties, residents, and the
# treatment and recovery spent there.
query BurdenByRegion {
  o__viewTreatmentAgainstBurdenGroupBy(by: [region], order_by: [{ aggregate: { sum: { treatmentSpent: desc } } }]) {
    groupKey
    aggregate {
      count
      sum {
        population
        treatmentSpent
      }
    }
  }
}

# The formulary's products by their risk -- shortage, recall, both or none: how many, how much
# stock they hold and how much Medicaid prescribes them.
query ProductsByRisk {
  p__viewProductRiskGroupBy(by: [risk], order_by: [{ aggregate: { count: desc } }]) {
    groupKey
    aggregate {
      count
      sum {
        onHandUnits
        prescriptions_2023
      }
    }
  }
}

# The critical products of the formulary in a current shortage, fewest days of supply first: what
# the pharmacy runs out of first.
query CriticalProductsAtRisk {
  p__viewProductRisk(
    where: { critical: { eq: true }, risk: { in: ["shortage", "shortage and recall"] } }
    order_by: [{ daysOfSupply: asc }]
    limit: 10
  ) {
    genericName
    manufacturer
    productNdc
    shortageAvailability
    worstRecallClass
    daysOfSupply
  }
}

# Each customers column as the latest profile run found it, emptiest first: its nulls, distinct
# values and range.
query CustomerColumns {
  h__viewCustomerColumns(order_by: [{ nullShare: desc }]) {
    columnName
    dataType
    nullShare
    distinctCount
    minValue
    maxValue
  }
}

# The shapes the phone numbers take: one column, four formats.
query PhoneFormats {
  h__viewCustomerFormats(where: { columnName: { eq: "phone" } }, order_by: [{ rank: asc }]) {
    rank
    shape
    rowCount
  }
}

# The commonest values of the country column: the United States spelled three ways among them.
query CountrySpellings {
  h__customerTopValues(
    where: { columnName: { eq: "country" } }
    order_by: [{ runTime: desc }, { rank: asc }]
    limit: 10
  ) {
    rank
    value
    rowCount
  }
}

# Each profile run of the customers table: when, how many rows, and the duplicate rows it found.
query ProfileRuns {
  h__customerProfileRuns(order_by: [{ runTime: desc }], limit: 10) {
    runTime
    status
    rowCount
    profiledRows
    duplicateRows
    duplicateShare
    durationMs
  }
}

# What each customers column plausibly holds, and the evidence: an email, a phone number, a
# postal code -- whatever its name says.
query PlausibleTypes {
  h__customerColumnTypes(order_by: [{ runTime: desc }, { columnName: asc }], limit: 10) {
    columnName
    plausibleType
    confidence
    evidence
  }
}

# The dataset the teams pull, by product category: its orders, revenue and margin. Run as finance
# the margins are what they are; run as data science they read 0 and the service orders are gone.
query DatasetByCategory {
  p__viewOrderMarginsGroupBy(by: [category], order_by: [{ aggregate: { sum: { revenue: desc } } }]) {
    groupKey
    aggregate {
      count
      sum {
        revenue
        margin
      }
    }
  }
}

# Each team's pulls of the dataset, as its consumer recorded them: how many, and how fast on average.
query PullsByTeam {
  p__pullsGroupBy(by: [consumer]) {
    groupKey
    aggregate {
      count
      avg {
        rows
        seconds
        rowsPerSec
      }
    }
  }
}

# Which checks admitted this version of silver: a silver sale, the check run that admitted its
# batch, and that run's every check, along the relationship ADMITTED_BY.
query ChecksThatAdmittedSilver {
  s__viewSilver(limit: 1, order_by: [{ saleId: asc }]) {
    saleId
    runId
    viewDqResults {
      checkName
      definition
      failingRows
      outcome
    }
  }
}

# What the bad batch failed on: every failing check, with how many rows of its batch failed it.
query WhatTheBadBatchFailedOn {
  s__viewDqResults(where: { outcome: { eq: "fail" } }, order_by: [{ checkName: asc }]) {
    batchId
    runId
    checkName
    definition
    failingRows
  }
}

# Every landed batch and how many of its checks passed and failed.
query EveryBatchAndItsOutcome {
  s__viewDqResultsGroupBy(by: [batchId, outcome], order_by: [{ groupKey: { batchId: asc } }]) {
    groupKey
    aggregate {
      count
    }
  }
}

# The batches landed into bronze, as delivered, and how many lines each holds: the bad batch is
# here, though it never reached silver.
query BatchesLandedInBronze {
  s__bronzeGroupBy(by: [batchId], order_by: [{ groupKey: { batchId: asc } }]) {
    groupKey
    aggregate {
      count
    }
  }
}

# Gold: totals by day and product, from the checked batches only.
query GoldRevenueByProduct {
  s__viewGold(order_by: [{ revenue: desc }]) {
    saleDay
    product
    sales
    items
    revenue
    minPrice
    maxPrice
  }
}

# Each desk's exposure in the report, as the report stands now: the corrected figures.
query ExposureNow {
  r__viewExposure(limit: 20) {
    desk
    exposure
    validFrom
  }
}

# Group reporting, as the group's analysts read it: US customers as they are, EU customers by the
# pseudonym the EU computed. Run as group_analyst.
query GroupCustomers {
  r__viewGroupCustomers(order_by: [{ joinedOn: desc }], limit: 20) {
    subsidiary
    customer
    country
    joinedOn
  }
}

# The reviews that say the battery dies (an Elasticsearch search, the phrase highlighted), each
# with the product it is about from the MongoDB catalog.
query BatteryComplaints {
  s__reviewsMatching(phrase: "battery dies", order_by: [{ rating: asc }], limit: 20) {
    rating
    highlightText
    product {
      name
      category
      batteryHours
    }
  }
}

# The ten lowest-rated products: the star ratings summed up by a MongoDB aggregation pipeline,
# each with its product from the catalog.
query LowestRatedProducts {
  s__ratingsByProduct(order_by: [{ avgStars: asc }], limit: 10) {
    avgStars
    ratings
    oneStar
    product {
      name
      category
      brand
    }
  }
}

# What the buyers of the Voltra Fit 2 smartwatch (product 6) also bought, most bought first: a
# Cypher query over who bought what in Neo4j, each product named from the MongoDB catalog.
query BoughtWithTheVoltraFit2 {
  s__boughtTogether(where: { productId: { eq: 6 } }, order_by: [{ customers: desc }], limit: 10) {
    customers
    alsoBought {
      name
      category
      price
    }
  }
}

# How many reviews give each number of stars, from the Elasticsearch reviews.
query ReviewsByRating {
  s__reviewsGroupBy(by: [rating], order_by: [{ groupKey: { rating: asc } }]) {
    groupKey
    aggregate {
      count
    }
  }
}

# Where Shakespeare echoes himself: the pairs of lines in different sonnets nearest in meaning,
# nearest first, each with the words of both lines.
query StrongestEchoes {
  s__viewEchoLines(order_by: [{ score: desc }], limit: 10) {
    score
    sonnet
    lineNo
    text
    echoSonnet
    echoLineNo
    echoText
  }
}

# The pairs of sonnets whose lines echo each other most: how many echoes run between them and how
# near they are on average, the most echoes first.
query SonnetsThatEchoEachOther {
  s__viewEchoLinesGroupBy(
    by: [sonnet, echoSonnet]
    order_by: [{ aggregate: { count: desc } }, { aggregate: { avg: { score: desc } } }]
    limit: 10
  ) {
    groupKey
    aggregate {
      count
      avg {
        score
      }
    }
  }
}

# The lines nearest in meaning to "the ravages of time", as the stored theme view holds them,
# nearest first.
query LinesOnTime {
  s__viewThemeTime(order_by: [{ score: desc }], limit: 10) {
    score
    sonnetNumber
    lineNo
    text
  }
}

# Which themes run through which sequence: for each theme, how many of the lines its search found
# are in the Fair Youth sonnets and how many in the Dark Lady sonnets.
query ThemesBySequence {
  s__viewThemeLinesGroupBy(
    by: [theme, sequence]
    order_by: [{ groupKey: { theme: asc } }, { groupKey: { sequence: asc } }]
  ) {
    groupKey
    aggregate {
      count
      avg {
        score
      }
    }
  }
}

# The sonnets each theme runs through most: for each theme and sonnet, how many of its lines the
# theme's search found.
query SonnetsAThemeRunsThrough {
  s__viewThemeLinesGroupBy(
    by: [theme, sonnet]
    order_by: [{ aggregate: { count: desc } }, { groupKey: { sonnet: asc } }]
    limit: 15
  ) {
    groupKey
    aggregate {
      count
    }
  }
}

# How many pets there are of each species: the query the tour hands the GraphQL explorer.
query PetsCountPerSpecies {
  ps__petsGroupBy(by: [species]) {
    groupKey
    aggregate {
      count
    }
  }
}

# The order-history screen's one query (app/index.html sends it as the signed-in customer): each
# order with its lines, the product of each line from the catalog, and its shipment from the
# shipping service -- three stores, one request. The customer reads only their own orders.
query OrderHistory {
  s__orders(order_by: [{ placedAt: desc }]) {
    id
    placedAt
    status
    customer {
      name
    }
    orderItems {
      line
      quantity
      unitPrice
      product {
        name
        category
        imageUrl
      }
    }
    shipment {
      carrier
      tracking
      promisedAt
      deliveredAt
    }
  }
}

# The analyst's view of shipping: each carrier's shipments and how many arrived after the date the
# customer was promised -- the same orders the order-history screen shows, read through the same
# relationships and rules.
query LateShipmentsByCarrier {
  s__viewLateShipmentsByCarrier(order_by: [{ late: desc }]) {
    carrier
    shipments
    late
  }
}

# Which regions placed the most orders in the last five minutes: the view the landing orders keep
# current, its answer kept in the response cache for ten seconds (@cached).
query BusiestRegionsNow @cached(ttl: 10) {
  s__viewOrdersLastFiveMinutes(order_by: [{ orders: desc }]) {
    region
    orders
    items
    revenue
    lastOrderAt
  }
}

# The latest orders as they land from the topic, each with the product and region it names.
query LatestOrders {
  s__orders(limit: 20, order_by: [{ orderedAt: desc }]) {
    orderId
    quantity
    orderedAt
    product {
      name
      unitPrice
    }
    region {
      name
    }
  }
}

# The latest orders, live: every batch that lands sends the list again.
subscription WatchTheOrders {
  s__orders(limit: 10, order_by: [{ orderedAt: desc }]) {
    orderId
    quantity
    orderedAt
    region {
      name
    }
  }
}

# Each order with the customer who placed it, through the relationship: in prod the real customers,
# in dev and test their fakes -- the join still matches, because both keys are faked alike.
query OrdersByCustomer {
  s__orders(order_by: [{ placedAt: desc }], limit: 10) {
    id
    placedAt
    status
    customer {
      name
      email
      city
    }
  }
}

# What each region spends, by product category: the same view in every environment.
query SalesByRegion {
  s__viewSalesByRegion(order_by: [{ revenue: desc }]) {
    region
    category
    orders
    revenue
  }
}

# The exploited vulnerabilities open in each team's code: how many, and how long the oldest has
# been past CISA's due date.
query ExploitedByTeam {
  s__viewExploitedInOurCodeGroupBy(by: [team], order_by: [{ aggregate: { count: desc } }]) {
    groupKey
    aggregate {
      count
      max {
        daysPastDue
      }
    }
  }
}

# The exploited vulnerabilities open in repositories that serve the internet, longest overdue first:
# where to start.
query InternetFacingAndExploited {
  s__viewExploitedInOurCode(
    where: { internetFacing: { eq: true } }
    order_by: [{ daysPastDue: desc }]
    limit: 20
  ) {
    repository
    packageName
    vulnerableVersion
    fixedVersion
    cveId
    vulnerabilityName
    knownRansomwareUse
    daysPastDue
  }
}

# Each open critical alert with its CVE's CVSS score, the weakness it is an instance of, and
# whether attackers are known to exploit it: a severity score alone does not say which to fix first.
query OpenAlertsWithTheirWeaknesses {
  s__dependabotAlerts(
    where: { state: { eq: "open" }, severity: { eq: "critical" } }
    order_by: [{ cveId: asc }]
    limit: 30
  ) {
    packageName
    cveId
    repository {
      name
    }
    cve {
      cvssV31Score
      kev {
        dueDate
      }
      weaknesses {
        weakness {
          cweId
          name
        }
      }
    }
  }
}

# The Dependabot alerts by state and severity: what is open, fixed and dismissed.
query AlertsByState {
  s__dependabotAlertsGroupBy(by: [state, severity], order_by: [{ aggregate: { count: desc } }]) {
    groupKey
    aggregate {
      count
    }
  }
}

# The slowest pages by path: each path the shop served, with how many requests and their average and
# longest time in milliseconds, the ten slowest by average first.
query SlowestPagesByPath {
  s__viewSlowestPagesGroupBy(
    by: [path]
    order_by: [{ aggregate: { avg: { pageMs: desc } } }, { groupKey: { path: asc } }]
    limit: 10
  ) {
    groupKey
    aggregate {
      count
      avg {
        pageMs
      }
      max {
        pageMs
      }
    }
  }
}

# The shop's statements by the table they read or wrote: how many, and their average and longest
# time in milliseconds, the slowest on average first.
query SlowStatementsByTable {
  s__viewRequestSqlGroupBy(
    by: [tableName]
    order_by: [{ aggregate: { avg: { durationMs: desc } } }, { groupKey: { tableName: asc } }]
  ) {
    groupKey
    aggregate {
      count
      avg {
        durationMs
      }
      max {
        durationMs
      }
    }
  }
}

# Customers who were served a server error, by region: how many customers, the errors they were
# served and the orders they have placed.
query CustomersServedErrorsByRegion {
  s__viewCustomersWith_5xxGroupBy(by: [region]) {
    groupKey
    aggregate {
      count
      sum {
        serverErrors
        orders
      }
    }
  }
}

# Requests whose statement failed in the database, by the page requested and the database's
# error code.
query DatabaseErrorsByPage {
  s__viewRequestsWithDbErrorsGroupBy(by: [path, stateCode]) {
    groupKey
    aggregate {
      count
    }
  }
}

# Products customers looked at that no order has included, by category: how many, how often they
# were viewed and their average price.
query ViewedNotBoughtByCategory {
  s__viewViewedNotBoughtGroupBy(by: [productCategory]) {
    groupKey
    aggregate {
      count
      sum {
        views
      }
      avg {
        productPrice
      }
    }
  }
}

# Statement times over every table the shop reads or writes: how many tables, the slowest
# statement of any, the average of their averages, and each table's own figures.
query StatementTimesOverall {
  s__viewSlowStatementsByTableAggregate {
    aggregate {
      count
      max {
        maxMs
      }
      avg {
        avgMs
      }
    }
    nodes {
      tableName
      statements
      avgMs
      p95Ms
      maxMs
    }
  }
}

# Every final with the FIFA member its winners stand for, through country_alias: the titles
# Wikipedia lists under West Germany are those of Germany.
query FinalsAndTheirWinners {
  w__finals(order_by: [{ year: asc }]) {
    year
    winners
    score
    winner {
      canonicalCountry
      fifaCode
    }
  }
}

query($order_id: Int!) {
